def isValidCouponCode(code):
    if len(code) != 10:
        return False
    digit_count = 0
    for c in code:
        if 'A' <= c <= 'Z' or '0' <= c <= '9':
            if '0' <= c <= '9':
                digit_count += 1
        else:
            return False
    return digit_count >= 2
